-- CHANGE LOG
-- 1 | maintainer@emeraldcoastsystemsgroup.com | The deterministic engine's prediction ledger on the native kernel: one row per algorithm (and the ensemble) per scanned symbol, resolved after its horizon into a hit or a miss. The Algorithms scan recorded into a table the native kernel never provisioned ("SQL table oshal_trading_predictions is not provisioned"), so every scanned symbol failed and the scan showed an empty table. Columns as the platform's trading schema declared them (plus book_id); every row carries user_sub.
CREATE TABLE IF NOT EXISTS oshal_trading_predictions (prediction_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_sub TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'paper' CHECK (mode IN ('paper','live')), symbol TEXT NOT NULL, algo TEXT NOT NULL, pred_dir TEXT NOT NULL CHECK (pred_dir IN ('up','down')), confidence NUMERIC(5,4), price NUMERIC(18,4) NOT NULL, basis TEXT, horizon_hrs INTEGER NOT NULL DEFAULT 24, resolved BOOLEAN NOT NULL DEFAULT false, actual_dir TEXT, actual_price NUMERIC(18,4), hit BOOLEAN, book_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_trd_pred_symbol_algo ON oshal_trading_predictions (symbol, algo, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_trd_pred_algo ON oshal_trading_predictions (algo, resolved);
CREATE INDEX IF NOT EXISTS idx_trd_pred_open_mode ON oshal_trading_predictions (mode, created_at) WHERE resolved = false;
